// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.json;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.JSONF;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.junit.jupiter.api.Test;

class JsonFunctionsTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final Literal DOC = json(
			"{\"name\":\"Ann\",\"age\":42,\"tags\":[\"a\",\"b\"],\"address\":{\"city\":\"Oslo\",\"zip\":null},"
					+ "\"items\":[{\"id\":1,\"price\":2.5},{\"id\":2,\"price\":1e2}],\"ok\":true}");

	private static Literal json(String s) {
		return VF.createLiteral(s, CoreDatatype.RDF.JSON);
	}

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	@Test
	void jsonValueMapsScalars() {
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.name"))).isEqualTo(str("Ann"));
		assertThat(new JsonValue().evaluate(VF, DOC, str("age"))).isEqualTo(VF.createLiteral(BigInteger.valueOf(42)));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.tags[1]"))).isEqualTo(str("b"));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.tags[-1]"))).isEqualTo(str("b"));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$['address']['city']"))).isEqualTo(str("Oslo"));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.items[0].price")))
				.isEqualTo(VF.createLiteral(new java.math.BigDecimal("2.5")));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.items[1].price"))).isEqualTo(VF.createLiteral(100.0));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.ok"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new JsonValue().evaluate(VF, str("{\"a\":1}"), str("$.a")))
				.isEqualTo(VF.createLiteral(BigInteger.ONE));
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, str("$.missing")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, str("$.address.zip")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, str("$.tags")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, str("$.tags[*]")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, str("not json"), str("$.a")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, str("$.[")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void jsonQueryWrapsMultipleMatches() {
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$.address")))
				.isEqualTo(json("{\"city\":\"Oslo\",\"zip\":null}"));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$.items[*].id"))).isEqualTo(json("[1,2]"));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$..city"))).isEqualTo(json("\"Oslo\""));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$..id"))).isEqualTo(json("[1,2]"));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$.tags.*"))).isEqualTo(json("[\"a\",\"b\"]"));
		// re-serialisation normalises number lexical forms (1e2 -> 100.0)
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$")).getLabel())
				.isEqualTo(DOC.getLabel().replace("1e2", "100.0"));
		assertThatThrownBy(() -> new JsonQuery().evaluate(VF, DOC, str("$.nope")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void existsKeysAndLength() {
		assertThat(new JsonExists().evaluate(VF, DOC, str("$.address.zip"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new JsonExists().evaluate(VF, DOC, str("$.address.street"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new JsonKeys().evaluate(VF, DOC))
				.isEqualTo(json("[\"name\",\"age\",\"tags\",\"address\",\"items\",\"ok\"]"));
		assertThat(new JsonKeys().evaluate(VF, DOC, str("$.address"))).isEqualTo(json("[\"city\",\"zip\"]"));
		assertThatThrownBy(() -> new JsonKeys().evaluate(VF, DOC, str("$.tags")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new JsonArrayLength().evaluate(VF, DOC, str("$.tags")))
				.isEqualTo(VF.createLiteral(BigInteger.TWO));
		assertThat(new JsonArrayLength().evaluate(VF, json("[]"))).isEqualTo(VF.createLiteral(BigInteger.ZERO));
		assertThatThrownBy(() -> new JsonArrayLength().evaluate(VF, DOC))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void constructors() {
		assertThat(new JsonObject().evaluate(VF, str("a"), VF.createLiteral(1), str("b"), VF.createIRI("urn:x"),
				str("c"), json("[1]"), str("d"), VF.createLiteral("x", "en")))
						.isEqualTo(json(
								"{\"a\":1,\"b\":{\"@id\":\"urn:x\"},\"c\":[1],\"d\":{\"@value\":\"x\",\"@language\":\"en\"}}"));
		assertThatThrownBy(() -> new JsonObject().evaluate(VF, str("a")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new JsonArray().evaluate(VF, VF.createLiteral(true), str("s"), VF.createLiteral(1.5)))
				.isEqualTo(json("[true,\"s\",1.5]"));
		assertThat(new JsonArray().evaluate(VF)).isEqualTo(json("[]"));
	}

	@Test
	void jsonSetCreatesPathsAndKeepsSourceIntact() {
		Literal source = json("{\"a\":{\"b\":1},\"l\":[1,2]}");
		assertThat(new JsonSet().evaluate(VF, source, str("$.a.b"), VF.createLiteral(2)))
				.isEqualTo(json("{\"a\":{\"b\":2},\"l\":[1,2]}"));
		assertThat(new JsonSet().evaluate(VF, source, str("$.a.c.d"), str("x")))
				.isEqualTo(json("{\"a\":{\"b\":1,\"c\":{\"d\":\"x\"}},\"l\":[1,2]}"));
		assertThat(new JsonSet().evaluate(VF, source, str("$.l[1]"), VF.createLiteral(9)))
				.isEqualTo(json("{\"a\":{\"b\":1},\"l\":[1,9]}"));
		assertThat(new JsonSet().evaluate(VF, source, str("$.l[5]"), VF.createLiteral(9)))
				.isEqualTo(json("{\"a\":{\"b\":1},\"l\":[1,2,9]}"));
		assertThat(new JsonSet().evaluate(VF, source, str("$.n"), json("{\"k\":true}")))
				.isEqualTo(json("{\"a\":{\"b\":1},\"l\":[1,2],\"n\":{\"k\":true}}"));
		// the cached source document must not have been mutated
		assertThat(new JsonQuery().evaluate(VF, source, str("$"))).isEqualTo(source);
		assertThatThrownBy(() -> new JsonSet().evaluate(VF, source, str("$.l[*]"), VF.createLiteral(1)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void allRegistered() {
		for (String name : new String[] { "jsonValue", "jsonQuery", "jsonExists", "jsonKeys", "jsonArrayLength",
				"jsonObject", "jsonArray", "jsonSet" }) {
			assertThat(FunctionRegistry.getInstance().get(JSONF.NAMESPACE + name)).as(name).isPresent();
		}
	}
}
